for t, cat, cu, serv, meals, ings, prep, low, high, fin in SC:
    R(F, t, cat, cu, 20, low * 60, serv, meals, ings,
      [prep, "Cover and cook on Low for %d hours or on High for %d hours, until tender. Slow cookers vary, so check toward the end" % (low, high), fin])

