for t, cat, cu, serv, meals, ings, prep, temp, mins, mid, fin in AF:
    c = round((temp - 32) * 5 / 9 / 5) * 5
    R(G, t, cat, cu, 15, mins + 3, serv, meals, ings,
      ["Preheat the air fryer to %d °F (%d °C) for 3 minutes" % (temp, c), prep,
       "Arrange in a single layer in the basket without crowding (cook in batches if needed) and air fry for %d minutes, %s. Smaller air fryers may need a few extra minutes" % (mins, mid), fin])
